const panel = document.querySelector('.xp-workshop-widget:last-child .xp-workshop-content');
if (!panel) throw Error('Macro panel unavailable');
const button = document.createElement('button');
button.className = 'mini-action';
button.textContent = 'Run A -> B sequence';
const status = document.createElement('p');
status.textContent = 'Idle';
panel.append(button, status);
let enabled = true;
let running = false;
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
button.onclick = async () => {
  if (!enabled || running) return;
  running = true; button.disabled = true;
  try {
    status.textContent = 'Pressing A';
    await xlink.command('press A 100');
    await sleep(500);
    if (!enabled) return;
    status.textContent = 'Pressing B';
    await xlink.command('press B 100');
    status.textContent = 'Sequence complete';
  } catch (e) { status.textContent = 'Error: ' + e.message; }
  finally { running = false; button.disabled = false; }
};
xlink.log('A/B sequence macro enabled');
return () => { enabled = false; button.onclick = null; };
